import{_ as n,H as s,f as e,i as p}from"./chunks/framework.BH2BK_3i.js";const b=JSON.parse('{"title":"12 | 多线程之锁优化（上）：深入了解Synchronized同步锁的优化方法","description":"","frontmatter":{},"headers":[{"level":2,"title":"Synchronized同步锁实现原理","slug":"synchronized同步锁实现原理","link":"#synchronized同步锁实现原理","children":[]},{"level":2,"title":"锁升级优化","slug":"锁升级优化","link":"#锁升级优化","children":[{"level":3,"title":"Java对象头","slug":"java对象头","link":"#java对象头","children":[]},{"level":3,"title":"1.偏向锁","slug":"_1-偏向锁","link":"#_1-偏向锁","children":[]},{"level":3,"title":"2.轻量级锁","slug":"_2-轻量级锁","link":"#_2-轻量级锁","children":[]},{"level":3,"title":"3.自旋锁与重量级锁","slug":"_3-自旋锁与重量级锁","link":"#_3-自旋锁与重量级锁","children":[]}]},{"level":2,"title":"动态编译实现锁消除/锁粗化","slug":"动态编译实现锁消除-锁粗化","link":"#动态编译实现锁消除-锁粗化","children":[]},{"level":2,"title":"减小锁粒度","slug":"减小锁粒度","link":"#减小锁粒度","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"Java性能调优实战/12-多线程之锁优化（上）：深入了解Synchronized同步锁的优化方法.md","filePath":"Java性能调优实战/12-多线程之锁优化（上）：深入了解Synchronized同步锁的优化方法.md","lastUpdated":1779815864000}'),i={name:"Java性能调优实战/12-多线程之锁优化（上）：深入了解Synchronized同步锁的优化方法.md"};function t(l,a,o,c,r,h){return s(),e("div",null,[...a[0]||(a[0]=[p(`<h1 id="_12-多线程之锁优化-上-深入了解synchronized同步锁的优化方法" tabindex="-1">12 | 多线程之锁优化（上）：深入了解Synchronized同步锁的优化方法 <a class="header-anchor" href="#_12-多线程之锁优化-上-深入了解synchronized同步锁的优化方法" aria-label="Permalink to &quot;12 | 多线程之锁优化（上）：深入了解Synchronized同步锁的优化方法&quot;">​</a></h1><p>你好，我是刘超。从这讲开始，我们就正式进入到第三模块——多线程性能调优。</p><p><strong>在并发编程中，多个线程访问同一个共享资源时，我们必须考虑如何维护数据的原子性。</strong> 在JDK1.5之前，Java是依靠Synchronized关键字实现锁功能来做到这点的。Synchronized是JVM实现的一种内置锁，锁的获取和释放是由JVM隐式实现。</p><p>到了JDK1.5版本，并发包中新增了Lock接口来实现锁功能，它提供了与Synchronized关键字类似的同步功能，只是在使用时需要显式获取和释放锁。</p><p>Lock同步锁是基于Java实现的，而Synchronized是基于底层操作系统的Mutex Lock实现的，每次获取和释放锁操作都会带来用户态和内核态的切换，从而增加系统性能开销。因此，在锁竞争激烈的情况下，Synchronized同步锁在性能上就表现得非常糟糕，它也常被大家称为重量级锁。</p><p>特别是在单个线程重复申请锁的情况下，JDK1.5版本的Synchronized锁性能要比Lock的性能差很多。例如，在Dubbo基于Netty实现的通信中，消费端向服务端通信之后，由于接收返回消息是异步，所以需要一个线程轮询监听返回信息。而在接收消息时，就需要用到锁来确保request session的原子性。如果我们这里使用Synchronized同步锁，那么每当同一个线程请求锁资源时，都会发生一次用户态和内核态的切换。</p><p>到了JDK1.6版本之后，Java对Synchronized同步锁做了充分的优化，甚至在某些场景下，它的性能已经超越了Lock同步锁。这一讲我们就来看看Synchronized同步锁究竟是通过了哪些优化，实现了性能地提升。</p><h2 id="synchronized同步锁实现原理" tabindex="-1">Synchronized同步锁实现原理 <a class="header-anchor" href="#synchronized同步锁实现原理" aria-label="Permalink to &quot;Synchronized同步锁实现原理&quot;">​</a></h2><p>了解Synchronized同步锁优化之前，我们先来看看它的底层实现原理，这样可以帮助我们更好地理解后面的内容。</p><p><strong>通常Synchronized实现同步锁的方式有两种，一种是修饰方法，一种是修饰方法块。</strong> 以下就是通过Synchronized实现的两种同步方法加锁的方式：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 关键字在实例方法上，锁为当前实例</span></span>
<span class="line"><span>	public synchronized void method1() {</span></span>
<span class="line"><span>	    // code</span></span>
<span class="line"><span>	}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>	// 关键字在代码块上，锁为括号里面的对象</span></span>
<span class="line"><span>	public void method2() {</span></span>
<span class="line"><span>	    Object o = new Object();</span></span>
<span class="line"><span>	    synchronized (o) {</span></span>
<span class="line"><span>	        // code</span></span>
<span class="line"><span>	    }</span></span>
<span class="line"><span>	}</span></span></code></pre></div><p>下面我们可以通过反编译看下具体字节码的实现，运行以下反编译命令，就可以输出我们想要的字节码：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>javac -encoding UTF-8 SyncTest.java  //先运行编译class文件命令</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>javap -v SyncTest.class //再通过javap打印出字节文件</span></span></code></pre></div><p>通过输出的字节码，你会发现：Synchronized在修饰同步代码块时，是由 monitorenter和monitorexit指令来实现同步的。进入monitorenter 指令后，线程将持有Monitor对象，退出monitorenter指令后，线程将释放该Monitor对象。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  public void method2();</span></span>
<span class="line"><span>    descriptor: ()V</span></span>
<span class="line"><span>    flags: ACC_PUBLIC</span></span>
<span class="line"><span>    Code:</span></span>
<span class="line"><span>      stack=2, locals=4, args_size=1</span></span>
<span class="line"><span>         0: new           #2</span></span>
<span class="line"><span>         3: dup</span></span>
<span class="line"><span>         4: invokespecial #1</span></span>
<span class="line"><span>         7: astore_1</span></span>
<span class="line"><span>         8: aload_1</span></span>
<span class="line"><span>         9: dup</span></span>
<span class="line"><span>        10: astore_2</span></span>
<span class="line"><span>        11: monitorenter //monitorenter 指令</span></span>
<span class="line"><span>        12: aload_2</span></span>
<span class="line"><span>        13: monitorexit  //monitorexit  指令</span></span>
<span class="line"><span>        14: goto          22</span></span>
<span class="line"><span>        17: astore_3</span></span>
<span class="line"><span>        18: aload_2</span></span>
<span class="line"><span>        19: monitorexit</span></span>
<span class="line"><span>        20: aload_3</span></span>
<span class="line"><span>        21: athrow</span></span>
<span class="line"><span>        22: return</span></span>
<span class="line"><span>      Exception table:</span></span>
<span class="line"><span>         from    to  target type</span></span>
<span class="line"><span>            12    14    17   any</span></span>
<span class="line"><span>            17    20    17   any</span></span>
<span class="line"><span>      LineNumberTable:</span></span>
<span class="line"><span>        line 18: 0</span></span>
<span class="line"><span>        line 19: 8</span></span>
<span class="line"><span>        line 21: 12</span></span>
<span class="line"><span>        line 22: 22</span></span>
<span class="line"><span>      StackMapTable: number_of_entries = 2</span></span>
<span class="line"><span>        frame_type = 255 /* full_frame */</span></span>
<span class="line"><span>          offset_delta = 17</span></span>
<span class="line"><span>          locals = [ class com/demo/io/SyncTest, class java/lang/Object, class java/lang/Object ]</span></span>
<span class="line"><span>          stack = [ class java/lang/Throwable ]</span></span>
<span class="line"><span>        frame_type = 250 /* chop */</span></span>
<span class="line"><span>          offset_delta = 4</span></span></code></pre></div><p>再来看以下同步方法的字节码，你会发现：当Synchronized修饰同步方法时，并没有发现monitorenter和monitorexit指令，而是出现了一个ACC_SYNCHRONIZED标志。</p><p>这是因为JVM使用了ACC_SYNCHRONIZED访问标志来区分一个方法是否是同步方法。当方法调用时，调用指令将会检查该方法是否被设置ACC_SYNCHRONIZED访问标志。如果设置了该标志，执行线程将先持有Monitor对象，然后再执行方法。在该方法运行期间，其它线程将无法获取到该Mointor对象，当方法执行完成后，再释放该Monitor对象。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>   public synchronized void method1();</span></span>
<span class="line"><span>    descriptor: ()V</span></span>
<span class="line"><span>    flags: ACC_PUBLIC, ACC_SYNCHRONIZED // ACC_SYNCHRONIZED 标志</span></span>
<span class="line"><span>    Code:</span></span>
<span class="line"><span>      stack=0, locals=1, args_size=1</span></span>
<span class="line"><span>         0: return</span></span>
<span class="line"><span>      LineNumberTable:</span></span>
<span class="line"><span>        line 8: 0</span></span></code></pre></div><p>通过以上的源码，我们再来看看Synchronized修饰方法是怎么实现锁原理的。</p><p>JVM中的同步是基于进入和退出管程（Monitor）对象实现的。每个对象实例都会有一个Monitor，Monitor可以和对象一起创建、销毁。Monitor是由ObjectMonitor实现，而ObjectMonitor是由C++的ObjectMonitor.hpp文件实现，如下所示：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ObjectMonitor() {</span></span>
<span class="line"><span>   _header = NULL;</span></span>
<span class="line"><span>   _count = 0; //记录个数</span></span>
<span class="line"><span>   _waiters = 0,</span></span>
<span class="line"><span>   _recursions = 0;</span></span>
<span class="line"><span>   _object = NULL;</span></span>
<span class="line"><span>   _owner = NULL;</span></span>
<span class="line"><span>   _WaitSet = NULL; //处于wait状态的线程，会被加入到_WaitSet</span></span>
<span class="line"><span>   _WaitSetLock = 0 ;</span></span>
<span class="line"><span>   _Responsible = NULL ;</span></span>
<span class="line"><span>   _succ = NULL ;</span></span>
<span class="line"><span>   _cxq = NULL ;</span></span>
<span class="line"><span>   FreeNext = NULL ;</span></span>
<span class="line"><span>   _EntryList = NULL ; //处于等待锁block状态的线程，会被加入到该列表</span></span>
<span class="line"><span>   _SpinFreq = 0 ;</span></span>
<span class="line"><span>   _SpinClock = 0 ;</span></span>
<span class="line"><span>   OwnerIsThread = 0 ;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>当多个线程同时访问一段同步代码时，多个线程会先被存放在ContentionList和_EntryList 集合中，处于block状态的线程，都会被加入到该列表。接下来当线程获取到对象的Monitor时，Monitor是依靠底层操作系统的Mutex Lock来实现互斥的，线程申请Mutex成功，则持有该Mutex，其它线程将无法获取到该Mutex，竞争失败的线程会再次进入ContentionList被挂起。</p><p>如果线程调用wait() 方法，就会释放当前持有的Mutex，并且该线程会进入WaitSet集合中，等待下一次被唤醒。如果当前线程顺利执行完方法，也将释放Mutex。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Java%E6%80%A7%E8%83%BD%E8%B0%83%E4%BC%98%E5%AE%9E%E6%88%98/images/101244/f78e6979c424cce677add97080811308.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Java%E6%80%A7%E8%83%BD%E8%B0%83%E4%BC%98%E5%AE%9E%E6%88%98/images/101244/f78e6979c424cce677add97080811308.jpg" alt=""></a></p><p>看完上面的讲解，相信你对同步锁的实现原理已经有个深入的了解了。总结来说就是，同步锁在这种实现方式中，因Monitor是依赖于底层的操作系统实现，存在用户态与内核态之间的切换，所以增加了性能开销。</p><h2 id="锁升级优化" tabindex="-1">锁升级优化 <a class="header-anchor" href="#锁升级优化" aria-label="Permalink to &quot;锁升级优化&quot;">​</a></h2><p>为了提升性能，JDK1.6引入了偏向锁、轻量级锁、重量级锁概念，来减少锁竞争带来的上下文切换，而正是新增的Java对象头实现了锁升级功能。</p><p>当Java对象被Synchronized关键字修饰成为同步锁后，围绕这个锁的一系列升级操作都将和Java对象头有关。</p><h3 id="java对象头" tabindex="-1">Java对象头 <a class="header-anchor" href="#java对象头" aria-label="Permalink to &quot;Java对象头&quot;">​</a></h3><p>在JDK1.6 JVM中，对象实例在堆内存中被分为了三个部分：对象头、实例数据和对齐填充。其中Java对象头由Mark Word、指向类的指针以及数组长度三部分组成。</p><p>Mark Word记录了对象和锁有关的信息。Mark Word在64位JVM中的长度是64bit，我们可以一起看下64位JVM的存储结构是怎么样的。如下图所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Java%E6%80%A7%E8%83%BD%E8%B0%83%E4%BC%98%E5%AE%9E%E6%88%98/images/101244/fd86f1b5cbac1f652bea58b039fbc8f8.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Java%E6%80%A7%E8%83%BD%E8%B0%83%E4%BC%98%E5%AE%9E%E6%88%98/images/101244/fd86f1b5cbac1f652bea58b039fbc8f8.jpg" alt=""></a></p><p>锁升级功能主要依赖于Mark Word中的锁标志位和释放偏向锁标志位，Synchronized同步锁就是从偏向锁开始的，随着竞争越来越激烈，偏向锁升级到轻量级锁，最终升级到重量级锁。下面我们就沿着这条优化路径去看下具体的内容。</p><h3 id="_1-偏向锁" tabindex="-1">1.偏向锁 <a class="header-anchor" href="#_1-偏向锁" aria-label="Permalink to &quot;1.偏向锁&quot;">​</a></h3><p>偏向锁主要用来优化同一线程多次申请同一个锁的竞争。在某些情况下，大部分时间是同一个线程竞争锁资源，例如，在创建一个线程并在线程中执行循环监听的场景下，或单线程操作一个线程安全集合时，同一线程每次都需要获取和释放锁，每次操作都会发生用户态与内核态的切换。</p><p>偏向锁的作用就是，当一个线程再次访问这个同步代码或方法时，该线程只需去对象头的Mark Word中去判断一下是否有偏向锁指向它的ID，无需再进入Monitor去竞争对象了。 <strong>当对象被当做同步锁并有一个线程抢到了锁时，锁标志位还是01，“是否偏向锁”标志位设置为1，并且记录抢到锁的线程ID，表示进入偏向锁状态。</strong></p><p>一旦出现其它线程竞争锁资源时，偏向锁就会被撤销。偏向锁的撤销需要等待全局安全点，暂停持有该锁的线程，同时检查该线程是否还在执行该方法，如果是，则升级锁，反之则被其它线程抢占。</p><p><strong>下图中红线流程部分为偏向锁获取和撤销流程：</strong></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Java%E6%80%A7%E8%83%BD%E8%B0%83%E4%BC%98%E5%AE%9E%E6%88%98/images/101244/d9f1e7fae6996a940e9471c47a455ba2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Java%E6%80%A7%E8%83%BD%E8%B0%83%E4%BC%98%E5%AE%9E%E6%88%98/images/101244/d9f1e7fae6996a940e9471c47a455ba2.png" alt=""></a></p><p>因此，在高并发场景下，当大量线程同时竞争同一个锁资源时，偏向锁就会被撤销，发生stop the word后， 开启偏向锁无疑会带来更大的性能开销，这时我们可以通过添加JVM参数关闭偏向锁来调优系统性能，示例代码如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-XX:-UseBiasedLocking //关闭偏向锁（默认打开）</span></span></code></pre></div><p>或</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-XX:+UseHeavyMonitors  //设置重量级锁</span></span></code></pre></div><h3 id="_2-轻量级锁" tabindex="-1">2.轻量级锁 <a class="header-anchor" href="#_2-轻量级锁" aria-label="Permalink to &quot;2.轻量级锁&quot;">​</a></h3><p>当有另外一个线程竞争获取这个锁时，由于该锁已经是偏向锁，当发现对象头Mark Word中的线程ID不是自己的线程ID，就会进行CAS操作获取锁，如果获取成功，直接替换Mark Word中的线程ID为自己的ID，该锁会保持偏向锁状态；如果获取锁失败，代表当前锁有一定的竞争，偏向锁将升级为轻量级锁。</p><p>轻量级锁适用于线程交替执行同步块的场景，绝大部分的锁在整个同步周期内都不存在长时间的竞争。</p><p><strong>下图中红线流程部分为升级轻量级锁及操作流程：</strong></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Java%E6%80%A7%E8%83%BD%E8%B0%83%E4%BC%98%E5%AE%9E%E6%88%98/images/101244/84f4d5dd908788fec0940431b4b912f0.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Java%E6%80%A7%E8%83%BD%E8%B0%83%E4%BC%98%E5%AE%9E%E6%88%98/images/101244/84f4d5dd908788fec0940431b4b912f0.png" alt=""></a></p><h3 id="_3-自旋锁与重量级锁" tabindex="-1">3.自旋锁与重量级锁 <a class="header-anchor" href="#_3-自旋锁与重量级锁" aria-label="Permalink to &quot;3.自旋锁与重量级锁&quot;">​</a></h3><p>轻量级锁CAS抢锁失败，线程将会被挂起进入阻塞状态。如果正在持有锁的线程在很短的时间内释放资源，那么进入阻塞状态的线程无疑又要申请锁资源。</p><p>JVM提供了一种自旋锁，可以通过自旋方式不断尝试获取锁，从而避免线程被挂起阻塞。这是基于大多数情况下，线程持有锁的时间都不会太长，毕竟线程被挂起阻塞可能会得不偿失。</p><p>从JDK1.7开始，自旋锁默认启用，自旋次数由JVM设置决定，这里我不建议设置的重试次数过多，因为CAS重试操作意味着长时间地占用CPU。</p><p>自旋锁重试之后如果抢锁依然失败，同步锁就会升级至重量级锁，锁标志位改为10。在这个状态下，未抢到锁的线程都会进入Monitor，之后会被阻塞在_WaitSet队列中。</p><p><strong>下图中红线流程部分为自旋后升级为重量级锁的流程：</strong></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Java%E6%80%A7%E8%83%BD%E8%B0%83%E4%BC%98%E5%AE%9E%E6%88%98/images/101244/2e912fc6de6faeb1713a10959e5f1e99.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Java%E6%80%A7%E8%83%BD%E8%B0%83%E4%BC%98%E5%AE%9E%E6%88%98/images/101244/2e912fc6de6faeb1713a10959e5f1e99.png" alt=""></a></p><p>在锁竞争不激烈且锁占用时间非常短的场景下，自旋锁可以提高系统性能。一旦锁竞争激烈或锁占用的时间过长，自旋锁将会导致大量的线程一直处于CAS重试状态，占用CPU资源，反而会增加系统性能开销。所以自旋锁和重量级锁的使用都要结合实际场景。</p><p>在高负载、高并发的场景下，我们可以通过设置JVM参数来关闭自旋锁，优化系统性能，示例代码如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-XX:-UseSpinning //参数关闭自旋锁优化(默认打开)</span></span>
<span class="line"><span>-XX:PreBlockSpin //参数修改默认的自旋次数。JDK1.7后，去掉此参数，由jvm控制</span></span></code></pre></div><h2 id="动态编译实现锁消除-锁粗化" tabindex="-1">动态编译实现锁消除/锁粗化 <a class="header-anchor" href="#动态编译实现锁消除-锁粗化" aria-label="Permalink to &quot;动态编译实现锁消除/锁粗化&quot;">​</a></h2><p>除了锁升级优化，Java还使用了编译器对锁进行优化。JIT 编译器在动态编译同步块的时候，借助了一种被称为逃逸分析的技术，来判断同步块使用的锁对象是否只能够被一个线程访问，而没有被发布到其它线程。</p><p>确认是的话，那么 JIT 编译器在编译这个同步块的时候不会生成 synchronized 所表示的锁的申请与释放的机器码，即消除了锁的使用。在 Java7 之后的版本就不需要手动配置了，该操作可以自动实现。</p><p>锁粗化同理，就是在 JIT 编译器动态编译时，如果发现几个相邻的同步块使用的是同一个锁实例，那么 JIT 编译器将会把这几个同步块合并为一个大的同步块，从而避免一个线程“反复申请、释放同一个锁”所带来的性能开销。</p><h2 id="减小锁粒度" tabindex="-1">减小锁粒度 <a class="header-anchor" href="#减小锁粒度" aria-label="Permalink to &quot;减小锁粒度&quot;">​</a></h2><p>除了锁内部优化和编译器优化之外，我们还可以通过代码层来实现锁优化，减小锁粒度就是一种惯用的方法。</p><p>当我们的锁对象是一个数组或队列时，集中竞争一个对象的话会非常激烈，锁也会升级为重量级锁。我们可以考虑将一个数组和队列对象拆成多个小对象，来降低锁竞争，提升并行度。</p><p>最经典的减小锁粒度的案例就是JDK1.8之前实现的ConcurrentHashMap版本。我们知道，HashTable是基于一个数组+链表实现的，所以在并发读写操作集合时，存在激烈的锁资源竞争，也因此性能会存在瓶颈。而ConcurrentHashMap就很很巧妙地使用了分段锁Segment来降低锁资源竞争，如下图所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Java%E6%80%A7%E8%83%BD%E8%B0%83%E4%BC%98%E5%AE%9E%E6%88%98/images/101244/c8306510d7562eb96c6f6b22a75e7592.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Java%E6%80%A7%E8%83%BD%E8%B0%83%E4%BC%98%E5%AE%9E%E6%88%98/images/101244/c8306510d7562eb96c6f6b22a75e7592.png" alt=""></a></p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>JVM在JDK1.6中引入了分级锁机制来优化Synchronized，当一个线程获取锁时，首先对象锁将成为一个偏向锁，这样做是为了优化同一线程重复获取导致的用户态与内核态的切换问题；其次如果有多个线程竞争锁资源，锁将会升级为轻量级锁，它适用于在短时间内持有锁，且分锁有交替切换的场景；轻量级锁还使用了自旋锁来避免线程用户态与内核态的频繁切换，大大地提高了系统性能；但如果锁竞争太激烈了，那么同步锁将会升级为重量级锁。</p><p>减少锁竞争，是优化Synchronized同步锁的关键。我们应该尽量使Synchronized同步锁处于轻量级锁或偏向锁，这样才能提高Synchronized同步锁的性能；通过减小锁粒度来降低锁竞争也是一种最常用的优化方法；另外我们还可以通过减少锁的持有时间来提高Synchronized同步锁在自旋时获取锁资源的成功率，避免Synchronized同步锁升级为重量级锁。</p><p>这一讲我们重点了解了Synchronized同步锁优化，这里由于字数限制，也为了你能更好地理解内容，目录中12讲的内容我拆成了两讲，在下一讲中，我会重点讲解Lock同步锁的优化方法。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>请问以下Synchronized同步锁对普通方法和静态方法的修饰有什么区别？</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 修饰普通方法</span></span>
<span class="line"><span>	public synchronized void method1() {</span></span>
<span class="line"><span>	    // code</span></span>
<span class="line"><span>	}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>	// 修饰静态方法</span></span>
<span class="line"><span>	public  synchronized static void method2() {</span></span>
<span class="line"><span>	    // code</span></span>
<span class="line"><span>	}</span></span></code></pre></div><p>期待在留言区看到你的答案。也欢迎你点击“请朋友读”，把今天的内容分享给身边的朋友，邀请他一起学习。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Java%E6%80%A7%E8%83%BD%E8%B0%83%E4%BC%98%E5%AE%9E%E6%88%98/images/101244/bbe343640d6b708832c4133ec53ed967.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Java%E6%80%A7%E8%83%BD%E8%B0%83%E4%BC%98%E5%AE%9E%E6%88%98/images/101244/bbe343640d6b708832c4133ec53ed967.jpg" alt="unpreview"></a></p>`,77)])])}const g=n(i,[["render",t]]);export{b as __pageData,g as default};
